-- Exact numeric snapshot tokens preserved; no live structure is auto-certified.
-- Missing certificates use the reviewed helper; matching rows are unchanged;
-- stale/excluded certificates abort. No automatic overwrite or delete.
-- Any exception before COMMIT aborts the entire transaction; never auto-retry.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '2min';
SET LOCAL client_encoding = 'UTF8';
DO $prerequisites$
DECLARE r record; installed record; trusted_owner oid;
BEGIN
 SELECT proowner INTO trusted_owner FROM pg_proc
 WHERE oid=to_regprocedure('public.submit_public_order(jsonb)') AND prosecdef;
 IF trusted_owner IS NULL OR trusted_owner IS DISTINCT FROM
   (SELECT oid FROM pg_roles WHERE rolname=current_user) THEN
   RAISE EXCEPTION 'Use the reviewed existing public submission owner'
     USING DETAIL='CURV_CERT_OWNER';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon')
   OR NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated')
