('configuration_private.validate_product_coverage(uuid)','5f67471f6e1cc5a1a69562aac908f310','void',false,'plpgsql','s',false,false,ARRAY['search_path=pg_catalog'],false),
('configuration_private.certify_product(uuid,jsonb,text)','16adeab7de5a84632041659ec391d18f','void',false,'plpgsql','v',false,false,ARRAY['search_path=pg_catalog'],false),
('configuration_private.assert_pricing_ready(uuid)','71ec9155e75f9db50adc71a3df0e68e5','void',false,'plpgsql','s',false,false,ARRAY['search_path=pg_catalog'],false),
('configuration_private.valid_pricing_snapshot(jsonb)','4dff473beadfc5e4b452db7605f41d08','boolean',false,'plpgsql','i',false,false,ARRAY['search_path=pg_catalog'],false),
('submission_private.reject(text)','a3c353401ba2f3cd28fe7e1f7e3c3fab','void',false,'plpgsql','v',false,false,ARRAY['search_path=pg_catalog'],false),
('submission_private.text_value(jsonb,integer)','949adbdf08db41a22147ea6dfb238529','text',false,'plpgsql','i',false,false,ARRAY['search_path=pg_catalog'],false),
('submission_private.uuid_value(jsonb)','0fc1edc677bb44ae4b13e5e4012629b3','uuid',false,'plpgsql','i',false,false,ARRAY['search_path=pg_catalog'],false),
('submission_private.normalize_phone_v2(text)','222da931a6da26bc42a3ada3d2c92639','text',false,'sql','i',false,true,ARRAY['search_path=pg_catalog'],false),
('submission_private.canonicalize_v2_intent(jsonb)','31b396fe48384a1ef865882387a391fb','jsonb',false,'plpgsql','s',false,false,ARRAY['search_path=pg_catalog','timezone=utc','datestyle=iso, ymd'],false),
('submission_private.fingerprint_v2_intent(jsonb)','14f23258f6e702446275be352a0f7d2f','text',false,'sql','s',false,false,ARRAY['search_path=pg_catalog'],false),
('submission_private.fingerprint_v1_payload(jsonb)','12a6f5ee3be12e84e287b425f5b50c2c','text',false,'plpgsql','i',false,false,ARRAY['search_path=pg_catalog'],false),
('submission_private.lock_submission_key(uuid)','fd592fe062a82f75301424d38d75d7f4','void',false,'plpgsql','v',false,false,ARRAY['search_path=pg_catalog'],false),
('submission_private.replay_or_prepare(jsonb)','555b7db925131e10905ad05f5ea3dfde','jsonb',false,'plpgsql','v',false,false,ARRAY['search_path=pg_catalog'],false),
('configuration_private.pricing_error(text)','ef85b7c32a33b5b3d25e845eb8ce57ce','void',false,'plpgsql','i',false,false,ARRAY['search_path=pg_catalog'],false),
('configuration_private.pricing_input_lines(jsonb)','1d57631dc4b57e43d60c582ef466d619','record',true,'plpgsql','i',false,false,ARRAY['search_path=pg_catalog'],false),
('configuration_private.price_order_configuration(jsonb)','77afaf26d3ca4223dcb735fff1ca823d','jsonb',false,'plpgsql','s',false,false,ARRAY['search_path=pg_catalog'],false),
('configuration_private.customer_pricing_review(jsonb)','83d5c59c387583ed2f2d0148c0589506','jsonb',false,'sql','i',false,false,ARRAY['search_path=pg_catalog'],false),
('public.quote_public_cart(jsonb)','c5b2ccb4f7b87117b8826596eea257eb','jsonb',false,'plpgsql','s',true,false,ARRAY['search_path=pg_catalog'],true),
('submission_private.validate_current_order(jsonb)','2fe970ca99737d0487298551c877208e','void',false,'plpgsql','v',false,false,ARRAY['search_path=pg_catalog'],false),
('public.submit_public_order_v2(jsonb)','d4161272b05e3a9449a82ae1f93ce123','jsonb',false,'plpgsql','v',true,false,ARRAY['search_path=pg_catalog'],true)
 ) AS expected(signature,body_md5,return_type,returns_set,language_name,
               volatility,security_definer,is_strict,expected_config,is_public_rpc)
 LOOP
   SELECT p.*,l.lanname INTO installed FROM pg_proc p
   JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(r.signature);
   IF NOT FOUND THEN
     RAISE EXCEPTION 'Required reviewed function missing: %',r.signature
       USING DETAIL='CURV_CERT_PREREQUISITE';
   END IF;
   IF installed.proowner IS DISTINCT FROM trusted_owner OR installed.prokind<>'f'
     OR installed.prorettype IS DISTINCT FROM to_regtype(r.return_type)::oid
     OR installed.proretset IS DISTINCT FROM r.returns_set
     OR installed.lanname IS DISTINCT FROM r.language_name
     OR installed.provolatile::text IS DISTINCT FROM r.volatility
     OR installed.prosecdef IS DISTINCT FROM r.security_definer
     OR installed.proisstrict IS DISTINCT FROM r.is_strict
     OR ARRAY(SELECT lower(v) FROM unnest(installed.proconfig) v ORDER BY lower(v))
       IS DISTINCT FROM ARRAY(SELECT lower(v) FROM unnest(r.expected_config) v ORDER BY lower(v))
     OR md5(btrim(replace(installed.prosrc,E'\r\n',E'\n'),E' \t\r\n')) IS DISTINCT FROM r.body_md5 THEN
     RAISE EXCEPTION 'Reviewed function ownership/definition/security drift: %',r.signature
       USING DETAIL='CURV_CERT_FUNCTION_DRIFT';
   END IF;
   IF EXISTS(SELECT 1 FROM aclexplode(coalesce(installed.proacl,acldefault('f',installed.proowner))) a
             WHERE a.grantee=0 AND a.privilege_type='EXECUTE')
     OR (r.is_public_rpc AND (
       NOT has_function_privilege('anon',installed.oid,'EXECUTE')
       OR NOT has_function_privilege('authenticated',installed.oid,'EXECUTE')
       OR installed.proargnames[1] IS DISTINCT FROM 'p_request'))
     OR (NOT r.is_public_rpc AND (
       has_function_privilege('anon',installed.oid,'EXECUTE')
       OR has_function_privilege('authenticated',installed.oid,'EXECUTE'))) THEN
     RAISE EXCEPTION 'Reviewed function ACL/parameter drift: %',r.signature
       USING DETAIL='CURV_CERT_PERMISSION_DRIFT';
   END IF;
 END LOOP;
