   OR has_schema_privilege('authenticated','configuration_private','USAGE')
   OR has_schema_privilege('anon','submission_private','USAGE')
   OR has_schema_privilege('authenticated','submission_private','USAGE')
   OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=to_regclass('configuration_private.product_pricing_certifications')
                 AND relkind='r' AND relrowsecurity AND NOT relforcerowsecurity AND relowner=trusted_owner) THEN
   RAISE EXCEPTION 'Private schema/certification table security drift'
     USING DETAIL='CURV_CERT_PERMISSION_DRIFT';
 END IF;
 FOR r IN SELECT role_name,permission FROM
   unnest(ARRAY['anon','authenticated']) AS roles(role_name)
   CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE','TRUNCATE']) AS privileges(permission)
 LOOP
   IF has_table_privilege(r.role_name,'configuration_private.product_pricing_certifications',r.permission) THEN
     RAISE EXCEPTION 'Public role has direct certification privilege'
       USING DETAIL='CURV_CERT_PERMISSION_DRIFT';
   END IF;
 END LOOP;
 FOR r IN SELECT * FROM (VALUES
   ('product_id','uuid'),('structure_version','smallint'),('expected_structure','jsonb'),
