   IF NOT EXISTS(SELECT 1 FROM pg_attribute
     WHERE attrelid=to_regclass('configuration_private.product_pricing_certifications')
       AND attname=r.column_name AND NOT attisdropped AND attnotnull
       AND atttypid=to_regtype(r.type_name)::oid) THEN
     RAISE EXCEPTION 'Certification column contract drift: %',r.column_name
       USING DETAIL='CURV_CERT_PREREQUISITE';
   END IF;
 END LOOP;
 FOR r IN SELECT unnest(ARRAY[
   'd0a1_override_product_choice','d0a1_override_size_choice',
   'd0a1_requirement_product_choice','d0a1_requirement_size_choice',
   'orders_public_submission_key_idx']) AS index_name
 LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_index
     WHERE indexrelid=to_regclass('public.'||r.index_name)
       AND indisunique AND indisvalid AND indisready) THEN
     RAISE EXCEPTION 'Missing/invalid reviewed unique index: %',r.index_name
       USING DETAIL='CURV_CERT_PREREQUISITE';
   END IF;
 END LOOP;
