     WHERE conrelid=to_regclass('public.orders') AND conname='d0b1_order_pricing_metadata' AND convalidated) THEN
   RAISE EXCEPTION 'Existing order metadata/idempotency prerequisite drift'
     USING DETAIL='CURV_CERT_PREREQUISITE';
