 LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_attribute
     WHERE attrelid=to_regclass('public.'||r.table_name) AND attname=r.column_name
       AND NOT attisdropped AND atttypid=to_regtype(r.type_name)::oid) THEN
     RAISE EXCEPTION 'Installed order column prerequisite drift: %.%',r.table_name,r.column_name
       USING DETAIL='CURV_CERT_PREREQUISITE';
   END IF;
 END LOOP;
