   WHERE c.conrelid=to_regclass('configuration_private.product_pricing_certifications')
     AND c.contype='p' AND c.convalidated AND i.indisunique AND i.indisvalid AND i.indisready
     AND i.indnkeyatts=1 AND pg_get_indexdef(i.indexrelid,1,true)='product_id') THEN
   RAISE EXCEPTION 'Certification primary-key prerequisite drift'
     USING DETAIL='CURV_CERT_PREREQUISITE';
 END IF;
END
