T11:04:53.508805+00:00","sort_order":0,"price_delta":40,"option_group_id":"ff3aa2ce-e4ab-4870-98e1-93ff8078b534"},{"id":"7c4e3426-a4ea-427c-ad73-b0815242e7c4","label":"Add Cheese","value":"yes","is_active":true,"created_at":"2026-10-10T11:09:01.030475+00:00","sort_order":0,"price_delta":30,"option_group_id":"232d1301-d072-48ed-a363-6d5af6a6d906"},{"id":"bab37892-3af1-4498-ad67-71271c9cad70","label":"8pcs","value":"8pcs","is_active":false,"created_at":"2026-10-10T11:09:09.751246+00:00","sort_order":0,"price_delta":60,"option_group_id":"232d1301-d072-48ed-a363-6d5af6a6d906"},{"id":"d496995e-4e81-4298-b51e-6d316fc2de83","label":"Katsuboshi (Tuna Flakes)","value":"katsuboshi_tuna_flakes","is_active":true,"created_at":"2026-10-10T11:04:31.671449+00:00","sort_order":0,"price_delta":30,"option_group_id":"ff3aa2ce-e4ab-4870-98e1-93ff8078b534"}],"defaults":[{"id":"f56cae5e-ead1-44a7-9a55-078c94dc1156","created_at":"2026-10-12T08:34:49.130242+00:00","product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","option_group_id":"80d86bbb-e100-496c-99c3-6c9b0c8d4323","option_choice_id":"36b07804-02c1-4f67-85b4-8ba127777543"}],"overrides":[{"id":"0c7d56dc-aac0-427b-9566-b36232d1801a","is_active":true,"created_at":"2026-10-12T08:34:49.130242+00:00","product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","price_delta":60,"product_size_id":"22fbd2e7-7c33-4e4d-b3a2-ccf0860cb322","option_choice_id":"7c4e3426-a4ea-427c-ad73-b0815242e7c4"},{"id":"e7d3b121-f626-4f32-b2cf-7a64deaab32a","is_active":true,"created_at":"2026-10-12T08:34:49.130242+00:00","product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","price_delta":90,"product_size_id":"30df5f88-3760-4e46-bb52-a304e2fa2f42","option_choice_id":"7c4e3426-a4ea-427c-ad73-b0815242e7c4"},{"id":"fc319eb1-0400-404f-b568-5ac0d5e9993a","is_active":true,"created_at":"2026-10-12T08:34:49.130242+00:00","product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","price_delta":30,"product_size_id":"5092934c-919e-4c53-8890-ca29316aa551","option_choice_id":"7c4e3426-a4ea-427c-ad73-b0815242e7c4"}],"product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","assignments":[{"id":"7d7106a5-1208-4fd4-9053-1b14d38a41dd","is_active":true,"created_at":"2026-10-12T08:34:49.130242+00:00","product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","sort_order":30,"is_required":false,"max_selections":1,"min_selections":0,"option_group_id":"232d1301-d072-48ed-a363-6d5af6a6d906"},{"id":"bb711593-d1e3-46ed-9709-8ba715d4da4a","is_active":true,"created_at":"2026-10-12T08:34:49.130242+00:00","product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","sort_order":10,"is_required":false,"max_selections":1,"min_selections":0,"option_group_id":"80d86bbb-e100-496c-99c3-6c9b0c8d4323"},{"id":"3c838182-804b-45c4-8eba-2aad67cf7771","is_active":true,"created_at":"2026-10-12T08:34:49.130242+00:00","product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","sort_order":20,"is_required":false,"max_selections":null,"min_selections":0,"option_group_id":"ff3aa2ce-e4ab-4870-98e1-93ff8078b534"}],"requirements":[{"id":"48b0de37-c263-498e-8978-2f152fb72371","is_active":true,"product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","specificity":"size","product_size_id":"22fbd2e7-7c33-4e4d-b3a2-ccf0860cb322","option_choice_id":"7c4e3426-a4ea-427c-ad73-b0815242e7c4"},{"id":"7be400d3-ba71-4dc1-8ad2-5edcc99c4959","is_active":true,"product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","specificity":"size","product_size_id":"30df5f88-3760-4e46-bb52-a304e2fa2f42","option_choice_id":"7c4e3426-a4ea-427c-ad73-b0815242e7c4"},{"id":"1d292212-3f47-44fc-9e1a-571f501bf46a","is_active":true,"product_id":"ff9e0d6f-2a1b-4b6b-a401-e02370224f39","specificity":"size","product_size_id":"5092934c-919e-4c53-8890-ca29316aa551","option_choice_id":"7c4e3426-a4ea-427c-ad73-b0815242e7c4"}],"compatibility":[],"structure_version":1}}
]}
$reviewed_snapshot$::jsonb;
 r jsonb;
 current_product record;
 current_structure jsonb;
 current_certification record;
 catalog_before jsonb;
 catalog_after jsonb;
 existing_before jsonb;
 mappings_before jsonb;
 mappings_after jsonb;
 inserted_count bigint:=0;
 skipped_count bigint:=0;
 ready_count bigint:=0;
 matched_count bigint;
 stale_count bigint;
 excluded_count bigint;
 expected_mappings constant jsonb:='{"assignments":117,"defaults":19,"hot_sizes":8,"temperature_tuples":24,"overrides":17,"requirements":17}'::jsonb;
BEGIN
 IF jsonb_array_length(reviewed_manifest->'inventory')<>93
   OR jsonb_array_length(reviewed_manifest->'products')<>59
   OR (SELECT count(DISTINCT (v->>'product_id')::uuid)
       FROM jsonb_array_elements(reviewed_manifest->'inventory') v)<>93
   OR (SELECT count(DISTINCT (v->>'product_id')::uuid)
       FROM jsonb_array_elements(reviewed_manifest->'products') v)<>59
   OR (SELECT count(*) FROM jsonb_array_elements(reviewed_manifest->'inventory') v
       WHERE v->>'catalog_state'='SELLABLE_CANDIDATE')<>59
   OR length(btrim(reviewed_manifest->>'review_note')) NOT BETWEEN 1 AND 1000 THEN
   RAISE EXCEPTION 'Reviewed scope input incomplete' USING DETAIL='CURV_CERT_REVIEW_REQUIRED';
 END IF;
 IF (SELECT count(*) FROM public.products)<>93
   OR EXISTS(SELECT 1 FROM public.products p WHERE NOT EXISTS(
      SELECT 1 FROM jsonb_array_elements(reviewed_manifest->'inventory') v
      WHERE (v->>'product_id')::uuid=p.id))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(reviewed_manifest->'inventory') v
      WHERE NOT EXISTS(SELECT 1 FROM public.products p WHERE p.id=(v->>'product_id')::uuid))
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(reviewed_manifest->'inventory') v
      WHERE (v->>'catalog_state'='SELLABLE_CANDIDATE') IS DISTINCT FROM EXISTS(
        SELECT 1 FROM jsonb_array_elements(reviewed_manifest->'products') a
        WHERE a->>'product_id'=v->>'product_id')) THEN
   RAISE EXCEPTION '93-product inventory or 59-product approved scope changed'
     USING DETAIL='CURV_CERT_SCOPE_DRIFT';
 END IF;
 -- Compare exact approved names/flags and current sellability for all 93 IDs.
 FOR r IN SELECT value FROM jsonb_array_elements(reviewed_manifest->'inventory') LOOP
   SELECT p.*,
     CASE WHEN cat.id IS NULL THEN 'CATEGORY_MISSING'
          WHEN NOT p.is_published THEN 'UNPUBLISHED'
          WHEN NOT p.is_available THEN 'UNAVAILABLE'
          WHEN NOT coalesce((to_jsonb(cat)->>'is_active')::boolean,false) THEN 'CATEGORY_INACTIVE_OR_UNKNOWN'
          WHEN p.archived_at IS NOT NULL THEN 'ARCHIVED'
          WHEN p.is_sold_out THEN 'SOLD_OUT'
          WHEN NOT EXISTS(SELECT 1 FROM public.product_sizes s WHERE s.product_id=p.id) THEN 'NO_SIZE'
          ELSE 'SELLABLE_CANDIDATE' END AS current_catalog_state
   INTO current_product FROM public.products p LEFT JOIN public.categories cat ON cat.id=p.category_id
   WHERE p.id=(r->>'product_id')::uuid;
   IF NOT FOUND OR
     (current_product.name,current_product.is_published,current_product.is_available,
      current_product.is_sold_out,current_product.archived_at,current_product.current_catalog_state)
     IS DISTINCT FROM
     (r->>'product_name',(r->>'published')::boolean,(r->>'available')::boolean,
      (r->>'sold_out')::boolean,(r->>'archived_at')::timestamptz,r->>'catalog_state') THEN
     RAISE EXCEPTION 'Approved product identity/state drift: %',r->>'product_id'
       USING DETAIL='CURV_CERT_PRODUCT_STATE_DRIFT';
   END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM configuration_private.product_pricing_certifications c
   WHERE c.product_id NOT IN (SELECT (v->>'product_id')::uuid
     FROM jsonb_array_elements(reviewed_manifest->'products') v)) THEN
   RAISE EXCEPTION 'Excluded/unreviewed certificate unexpectedly exists'
     USING DETAIL='CURV_CERT_EXCLUDED_CERTIFICATION';
 END IF;
SELECT jsonb_build_object(
 'products',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.products t),'[]'::jsonb),
 'categories',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.categories t),'[]'::jsonb),
 'product_sizes',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_sizes t),'[]'::jsonb),
 'product_option_groups',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_option_groups t),'[]'::jsonb),
 'option_groups',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.option_groups t),'[]'::jsonb),
 'option_choices',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.option_choices t),'[]'::jsonb),
 'product_option_defaults',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_option_defaults t),'[]'::jsonb),
 'product_size_option_choice_compatibility',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_size_option_choice_compatibility t),'[]'::jsonb),
 'product_option_choice_price_overrides',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_option_choice_price_overrides t),'[]'::jsonb),
 'product_option_choice_override_requirements',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_option_choice_override_requirements t),'[]'::jsonb)
) INTO catalog_before;
SELECT jsonb_build_object(
 'assignments',(SELECT count(*) FROM public.product_option_groups a WHERE a.is_active AND a.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'defaults',(SELECT count(*) FROM public.product_option_defaults d WHERE d.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'hot_sizes',(SELECT count(*) FROM public.product_sizes s WHERE s.label='12oz Hot' AND s.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'temperature_tuples',(SELECT count(*) FROM public.product_size_option_choice_compatibility t WHERE t.is_active AND t.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'overrides',(SELECT count(*) FROM public.product_option_choice_price_overrides o WHERE o.is_active AND o.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'requirements',(SELECT count(*) FROM public.product_option_choice_override_requirements requirement WHERE requirement.is_active AND requirement.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v))
) INTO mappings_before;
 IF mappings_before IS DISTINCT FROM expected_mappings THEN
   RAISE EXCEPTION 'Approved repair totals changed' USING DETAIL='CURV_CERT_MAPPING_DRIFT';
 END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(c) ORDER BY c.product_id),'[]'::jsonb)
 INTO existing_before FROM configuration_private.product_pricing_certifications c;
 -- Validate every snapshot/certificate before the first persistent write.
 FOR r IN SELECT value FROM jsonb_array_elements(reviewed_manifest->'products') LOOP
   IF jsonb_typeof(r->'expected_structure') IS DISTINCT FROM 'object'
     OR r->'expected_structure'->'structure_version' IS DISTINCT FROM '1'::jsonb
     OR r->'expected_structure'->>'product_id' IS DISTINCT FROM r->>'product_id' THEN
     RAISE EXCEPTION 'Invalid reviewed structure contract' USING DETAIL='CURV_CERT_REVIEW_REQUIRED';
   END IF;
   current_structure:=configuration_private.catalog_structure((r->>'product_id')::uuid);
   IF current_structure IS DISTINCT FROM r->'expected_structure' THEN
     RAISE EXCEPTION 'Live structure changed after independent review: %',r->>'product_id'
       USING DETAIL='CURV_CERT_SNAPSHOT_DRIFT';
   END IF;
   SELECT * INTO current_certification FROM configuration_private.product_pricing_certifications
   WHERE product_id=(r->>'product_id')::uuid;
   IF FOUND AND (current_certification.structure_version IS DISTINCT FROM 1
     OR current_certification.expected_structure IS DISTINCT FROM r->'expected_structure') THEN
     RAISE EXCEPTION 'Stale/mismatched existing certificate requires review: %',r->>'product_id'
       USING DETAIL='CURV_CERT_EXISTING_COLLISION';
   END IF;
   PERFORM configuration_private.validate_product_coverage((r->>'product_id')::uuid);
 END LOOP;
 FOR r IN SELECT value FROM jsonb_array_elements(reviewed_manifest->'products') LOOP
   IF EXISTS(SELECT 1 FROM configuration_private.product_pricing_certifications
             WHERE product_id=(r->>'product_id')::uuid) THEN
     skipped_count:=skipped_count+1;
   ELSE
     PERFORM configuration_private.certify_product(
       (r->>'product_id')::uuid,r->'expected_structure',reviewed_manifest->>'review_note');
     inserted_count:=inserted_count+1;
   END IF;
 END LOOP;
 -- Every product must independently pass the reviewed runtime readiness gate.
 FOR r IN SELECT value FROM jsonb_array_elements(reviewed_manifest->'products') LOOP
   PERFORM configuration_private.assert_pricing_ready((r->>'product_id')::uuid);
   ready_count:=ready_count+1;
 END LOOP;
 SELECT count(*) FILTER(WHERE c.structure_version=1 AND c.expected_structure=expected.value->'expected_structure'),
        count(*) FILTER(WHERE c.product_id IS NULL OR c.structure_version IS DISTINCT FROM 1
                            OR c.expected_structure IS DISTINCT FROM expected.value->'expected_structure')
 INTO matched_count,stale_count
 FROM jsonb_array_elements(reviewed_manifest->'products') AS expected(value)
 LEFT JOIN configuration_private.product_pricing_certifications c ON c.product_id=(expected.value->>'product_id')::uuid;
 SELECT count(*) INTO excluded_count FROM configuration_private.product_pricing_certifications c
 WHERE c.product_id NOT IN(SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v);
 IF matched_count<>59 OR stale_count<>0 OR excluded_count<>0 OR ready_count<>59
   OR inserted_count+skipped_count<>59
   OR (SELECT count(*) FROM configuration_private.product_pricing_certifications)<>59 THEN
   RAISE EXCEPTION 'Final certification counts/readiness invalid'
     USING DETAIL='CURV_CERT_POSTFLIGHT';
 END IF;
 -- Matching existing certificates must not have been refreshed or overwritten.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(existing_before) b
   WHERE NOT EXISTS(SELECT 1 FROM configuration_private.product_pricing_certifications c
     WHERE c.product_id=(b->>'product_id')::uuid AND to_jsonb(c)=b)) THEN
   RAISE EXCEPTION 'A matching pre-existing certificate was changed'
     USING DETAIL='CURV_CERT_POSTFLIGHT';
 END IF;
SELECT jsonb_build_object(
 'assignments',(SELECT count(*) FROM public.product_option_groups a WHERE a.is_active AND a.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'defaults',(SELECT count(*) FROM public.product_option_defaults d WHERE d.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'hot_sizes',(SELECT count(*) FROM public.product_sizes s WHERE s.label='12oz Hot' AND s.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'temperature_tuples',(SELECT count(*) FROM public.product_size_option_choice_compatibility t WHERE t.is_active AND t.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'overrides',(SELECT count(*) FROM public.product_option_choice_price_overrides o WHERE o.is_active AND o.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v)),
 'requirements',(SELECT count(*) FROM public.product_option_choice_override_requirements requirement WHERE requirement.is_active AND requirement.product_id IN (SELECT (v->>'product_id')::uuid FROM jsonb_array_elements(reviewed_manifest->'products') v))
) INTO mappings_after;
SELECT jsonb_build_object(
 'products',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.products t),'[]'::jsonb),
 'categories',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.categories t),'[]'::jsonb),
 'product_sizes',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_sizes t),'[]'::jsonb),
 'product_option_groups',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_option_groups t),'[]'::jsonb),
 'option_groups',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.option_groups t),'[]'::jsonb),
 'option_choices',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.option_choices t),'[]'::jsonb),
 'product_option_defaults',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_option_defaults t),'[]'::jsonb),
 'product_size_option_choice_compatibility',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_size_option_choice_compatibility t),'[]'::jsonb),
 'product_option_choice_price_overrides',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_option_choice_price_overrides t),'[]'::jsonb),
 'product_option_choice_override_requirements',coalesce((SELECT jsonb_agg(to_jsonb(t) ORDER BY to_jsonb(t)::text COLLATE "C") FROM public.product_option_choice_override_requirements t),'[]'::jsonb)
) INTO catalog_after;
 IF mappings_after IS DISTINCT FROM expected_mappings
   OR mappings_after IS DISTINCT FROM mappings_before
   OR catalog_after IS DISTINCT FROM catalog_before THEN
   RAISE EXCEPTION 'Certification changed catalog/menu/state or mapping totals'
     USING DETAIL='CURV_CERT_POSTFLIGHT_CATALOG_CHANGED';
 END IF;
 INSERT INTO pg_temp._curv_certification_result VALUES
   (matched_count,inserted_count,skipped_count,excluded_count,stale_count,ready_count,59);
END
$certification$;
-- This result must be followed by successful COMMIT to establish persistence.
SELECT certified_matching,inserted_now,skipped_matching,excluded_certifications,
       stale_mismatched,pricing_ready_count,expected_scope_count
FROM pg_temp._curv_certification_result;
COMMIT;
